import datetime
from typing import Dict, Any, List

class ReportGenerator:
    @staticmethod
    def create_markdown_report(title: str, doc_names: List[str], summary_data: Dict[str, Any], gap_data: Dict[str, Any]) -> str:
        date_str = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        
        md = f"""# {title}
*Generated by ResearchMate AI on {date_str}*

---

## 1. Executive Summary
{summary_data.get('executive_summary', 'No executive summary available.')}

## 2. Analyzed Documents
{chr(10).join([f"- **{name}**" for name in doc_names])}

## 3. Individual Paper Findings
- **Paper Title:** {summary_data.get('paper_title', 'N/A')}
- **Authors:** {summary_data.get('authors', 'N/A')} ({summary_data.get('publication_year', 'N/A')})
- **Methodology:** {summary_data.get('methodology', 'N/A')}
- **Dataset:** {summary_data.get('dataset_or_sample', 'N/A')}

### Key Findings
{chr(10).join([f"- {item}" for item in summary_data.get('important_findings', [])]) or "None extracted."}

### Identified Limitations
{chr(10).join([f"- {item}" for item in summary_data.get('limitations', [])]) or "None extracted."}

## 4. Evidence-Grounded Research Gaps
"""
        gaps = gap_data.get("research_gaps", [])
        if gaps:
            for g in gaps:
                md += f"""
### {g.get('gap_title', 'Research Gap')}
- **Confidence:** {g.get('confidence_level', 'Medium')}
- **Source Paper:** {g.get('source_paper', 'N/A')}
- **Description:** {g.get('description', '')}
- **Evidence:** {g.get('supporting_evidence', '')}
"""
        else:
            md += "\nNo explicit research gaps identified from available evidence.\n"

        md += "\n---\n*Disclaimer: AI-generated analysis based exclusively on uploaded source documents.*"
        return md